register_both:
using WebCommander.Client;
using WebCommander.Config;

var auth = new AuthConfig(
    baseUrl: Environment.GetEnvironmentVariable("WC_BASE_URL")!,
    clientId: Environment.GetEnvironmentVariable("WC_CLIENT_ID")!,
    clientSecret: Environment.GetEnvironmentVariable("WC_CLIENT_SECRET")!,
    clientName: "default",
    authBaseUrl: Environment.GetEnvironmentVariable("WC_AUTH_BASE_URL"));
var legacyAuth = new AuthConfig(
    baseUrl: Environment.GetEnvironmentVariable("WC_LEGACY_BASE_URL")!,
    clientId: Environment.GetEnvironmentVariable("WC_LEGACY_CLIENT_ID")!,
    clientSecret: Environment.GetEnvironmentVariable("WC_LEGACY_CLIENT_SECRET")!,
    redirectUri: Environment.GetEnvironmentVariable("WC_LEGACY_REDIRECT_URI")!,
    authString: Environment.GetEnvironmentVariable("WC_LEGACY_AUTH_STRING")!,
    clientName: "legacy");

ClientRegistry.RegisterInstances([
    new SdkConfig(auth, raiseOnError: true),
    new SdkConfig(legacyAuth, raiseOnError: true),
]);

await using var client = WebCommanderClient.BuildClient();
await using var legacyClient = WebCommanderClient.BuildClient("legacy");
